SELECT sum(CASE WHEN (bi_fact_position_daily.position_type IN (?)) THEN bi_fact_position_daily.balance_rc END) AS m0
FROM bi_fact_position_daily LEFT OUTER JOIN bi_dim_branch ON bi_dim_branch.organization_id = bi_fact_position_daily.organization_id AND bi_dim_branch.bank_id = bi_fact_position_daily.bank_id AND bi_dim_branch.branch_code = bi_fact_position_daily.branch_code LEFT OUTER JOIN bi_dim_counterparty ON bi_dim_counterparty.organization_id = bi_fact_position_daily.organization_id AND bi_dim_counterparty.bank_id = bi_fact_position_daily.bank_id AND bi_dim_counterparty.counterparty_id = bi_fact_position_daily.counterparty_id
WHERE bi_fact_position_daily.organization_id = ? AND bi_fact_position_daily.bank_id = ? AND bi_fact_position_daily.as_of_date = ? AND bi_dim_branch.branch_code = ? AND bi_dim_branch.branch_code != ? AND bi_fact_position_daily.grade IN (?, ?) AND (bi_fact_position_daily.grade NOT IN (?)) AND bi_fact_position_daily.ifrs9_stage > ? AND bi_fact_position_daily.ifrs9_stage >= ? AND bi_fact_position_daily.ifrs9_stage < ? AND bi_fact_position_daily.ifrs9_stage <= ? AND bi_fact_position_daily.ifrs9_stage BETWEEN ? AND ? AND bi_dim_counterparty.counterparty_id IS NOT NULL AND bi_fact_position_daily.employer IS NULL AND (bi_fact_position_daily.sector LIKE '%' || ? || '%' ESCAPE '/') AND bi_fact_position_daily.non_performing = 0 AND bi_dim_branch.region IN (?, ?)
 LIMIT ? OFFSET ?
